QTR_QuestData["12101"] = QTR_QuestData["12101"] or {}
if not QTR_QuestData["12101"]["Title"] or QTR_QuestData["12101"]["Title"] == "" then
  QTR_QuestData["12101"]["Title"] = "Il bravo dottore..."
end
if not QTR_QuestData["12101"]["Description"] or QTR_QuestData["12101"]["Description"] == "" then
  QTR_QuestData["12101"]["Description"] = "I nostri alleati dei Non Morti hanno inviato qui un gruppo di alchimisti per aiutarci a distruggere il Flagello a Wrathgate. Uno di loro, il dottor Sintar Malefious, è esperto nella putrefazione del Flagello e nei metodi per contenerne la diffusione. In precedenza, avevo raggiunto un accordo con lui riguardo alla creazione di un vaccino per la fauna selvatica. Da allora, sta aspettando un organo.NEW_LINENEW_LINEConsegna questo organo resistente alla decomposizione al dottor Malefious e fagli sapere che proviene da me. Lui ti indicherà il tuo prossimo compito."
end
if not QTR_QuestData["12101"]["Objectives"] or QTR_QuestData["12101"]["Objectives"] == "" then
  QTR_QuestData["12101"]["Objectives"] = "Consegna l'organo resistente alla putrefazione al dottor Sintar Malefious presso il Martello di Agmar.NEW_LINE"
end
if not QTR_QuestData["12101"]["Progress"] or QTR_QuestData["12101"]["Progress"] == "" then
