end
if not QTR_QuestData["12101"]["Completion"] or QTR_QuestData["12101"]["Completion"] == "" then
  QTR_QuestData["12101"]["Completion"] = "Quel goffo bovino ha effettivamente ottenuto un organo resistente alla putrefazione? Maledizioni... Ero certo che quel compito avrebbe tenuto la sua mente deforme occupata fino al prossimo millennio.NEW_LINENEW_LINEBene, dammelo qui. YOUR_GENDER(ragazzo;ragazza)Ho molte cose da fare senza che le vostre misere esigenze mi ostacolino."
end

QTR_QuestData["12102"] = QTR_QuestData["12102"] or {}
if not QTR_QuestData["12102"]["Title"] or QTR_QuestData["12102"]["Title"] == "" then
  QTR_QuestData["12102"]["Title"] = "Alla ricerca del lillà rubino"
