QTR_QuestData["12324"] = QTR_QuestData["12324"] or {}
if not QTR_QuestData["12324"]["Title"] or QTR_QuestData["12324"]["Title"] == "" then
  QTR_QuestData["12324"]["Title"] = "Eliminateli"
end
if not QTR_QuestData["12324"]["Description"] or QTR_QuestData["12324"]["Description"] == "" then
  QTR_QuestData["12324"]["Description"] = "Non solo questo porto è infestato da codardi dell'Alleanza, ma, per peggiorare le cose, ci sono ancora dipendenti della Venture Company barricati in alcuni degli edifici. Non valgono il tempo necessario per ucciderli e, comunque, non posso permettermi di perdere guerrieri.NEW_LINENEW_LINEForse possiamo \"convincerli\" ad andare verso la loro nave. Prendi questa bomba fumogena e usala per far uscire i rimanenti dai loro nascondigli nella baracca, nella segheria o nelle stalle. Attenzione a non avvicinarti troppo; non si sa mai quali malattie possano avere."
end
if not QTR_QuestData["12324"]["Objectives"] or QTR_QuestData["12324"]["Objectives"] == "" then
  QTR_QuestData["12324"]["Objectives"] = "Utilizza la bomba fumogena per allontanare 20 Allontana i membri della Venture Company dai loro edifici e poi riferisci a Stone Guard Ragetotem."
end
if not QTR_QuestData["12324"]["Progress"] or QTR_QuestData["12324"]["Progress"] == "" then
  QTR_QuestData["12324"]["Progress"] = "Hai eliminato tutti i parassiti della Venture Company?"
end
if not QTR_QuestData["12324"]["Completion"] or QTR_QuestData["12324"]["Completion"] == "" then
  QTR_QuestData["12324"]["Completion"] = "Il generale sarà contento che tu abbia risolto il problema della Venture Company. Ora, gli uomini possono concentrarsi sul respingere l'Alleanza."
end

QTR_QuestData["12327"] = QTR_QuestData["12327"] or {}
if not QTR_QuestData["12327"]["Title"] or QTR_QuestData["12327"]["Title"] == "" then
  QTR_QuestData["12327"]["Title"] = "Esperienza extracorporea"
end
if not QTR_QuestData["12327"]["Description"] or QTR_QuestData["12327"]["Description"] == "" then
  QTR_QuestData["12327"]["Description"] = "Ah, cerchi una visione del passato. Sei una persona YOUR_RACE.NEW_LINENEW_LINEOgni volta che qualcuno viene per una lettura, sembra che chiedano sempre del futuro.  Quando si raggiunge la mia età, si impara che scrutare il passato, più spesso che no, è più utile.NEW_LINENEW_LINEBevi questa pozione e guarda nella mia sfera di cristallo. Vediamo che conoscenza possiamo ottenere."
end
if not QTR_QuestData["12327"]["Objectives"] or QTR_QuestData["12327"]["Objectives"] == "" then
  QTR_QuestData["12327"]["Objectives"] = "Bevi la Pozione di Seta vicino alla Sfera di Cristallo di Ruuna e osserva la Visione del Passato."
end
if not QTR_QuestData["12327"]["Progress"] or QTR_QuestData["12327"]["Progress"] == "" then
