  QTR_QuestData["12327"]["Completion"] = "Hai imparato qualcosa dalla tua visione? Hai menzionato Solstice Village durante la tua trance, ed è la seconda volta che qualcuno pronuncia il nome di quel luogo oggi."
end

QTR_QuestData["12328"] = QTR_QuestData["12328"] or {}
if not QTR_QuestData["12328"]["Title"] or QTR_QuestData["12328"]["Title"] == "" then
  QTR_QuestData["12328"]["Title"] = "La richiesta di Ruuna"
end
if not QTR_QuestData["12328"]["Description"] or QTR_QuestData["12328"]["Description"] == "" then
  QTR_QuestData["12328"]["Description"] = "Non ti farò pagare per i miei servizi, perché posso prevedere che le tue azioni siano necessarie e che molto dipenda da ciò che imparerai oggi.NEW_LINENEW_LINETuttavia, ti chiederò di raccogliere un reagente per me.  Ottieni la polvere di gossamero dalle falene nutrici che si trovano a nord-est di qui.  Fallo e preparerò una pozione che ti porterà al tempo e al luogo in cui si sono svolti gli eventi che devi assistere."
end
if not QTR_QuestData["12328"]["Objectives"] or QTR_QuestData["12328"]["Objectives"] == "" then
