end
if not QTR_QuestData["12328"]["Completion"] or QTR_QuestData["12328"]["Completion"] == "" then
  QTR_QuestData["12328"]["Completion"] = "Bene. Queste andranno benissimo.NEW_LINENEW_LINEPreparerò la pozione per te in un attimo."
end

QTR_QuestData["12329"] = QTR_QuestData["12329"] or {}
if not QTR_QuestData["12329"]["Title"] or QTR_QuestData["12329"]["Title"] == "" then
  QTR_QuestData["12329"]["Title"] = "Fato e coincidenza"
end
if not QTR_QuestData["12329"]["Description"] or QTR_QuestData["12329"]["Description"] == "" then
  QTR_QuestData["12329"]["Description"] = "In questo mondo, ci sono due tipi di persone, YOUR_NAME.  Coloro che credono nel caso e coloro che non ci credono.NEW_LINENEW_LINEIl giorno in cui ho perso la vista, mi è stato donato il dono della chiaroveggenza. Immagino che possiate indovinare che tipo di persona io sia.NEW_LINENEW_LINEIn precedenza, una giovane donna di nome Sasha ha ricevuto la stessa visione che hai ricevuto tu. Vorrai parlarle.NEW_LINENEW_LINELa troverai direttamente a est da qui, alla White Pine Trading Post, sulla strada per Solstice Village."
end
if not QTR_QuestData["12329"]["Objectives"] or QTR_QuestData["12329"]["Objectives"] == "" then
