end

QTR_QuestData["12418"] = QTR_QuestData["12418"] or {}
if not QTR_QuestData["12418"]["Title"] or QTR_QuestData["12418"]["Title"] == "" then
  QTR_QuestData["12418"]["Title"] = "Attraverso campi di fuoco"
