if not QTR_QuestData["12418"]["Description"] or QTR_QuestData["12418"]["Description"] == "" then
  QTR_QuestData["12418"]["Description"] = "Ho un'ultima missione per te, YOUR_RACE... una missione che dovrebbe cambiare le sorti di questa battaglia.NEW_LINENEW_LINERitorna al santuario e uccidi i negromanti che alimentano questo attacco. Una volta che saranno morti, dovremo essere in grado di respingere queste forze e riconquistare il santuario.NEW_LINENEW_LINEDevo anche che tu trovi la fonte della corruzione che si trova sotto il santuario e che tu la elimini.NEW_LINENEW_LINESo che vi ho chiesto molto, ma se fate questo per me, vinceremo questa battaglia."
end
if not QTR_QuestData["12418"]["Objectives"] or QTR_QuestData["12418"]["Objectives"] == "" then
