if not QTR_QuestData["12496"]["Objectives"] or QTR_QuestData["12496"]["Objectives"] == "" then
  QTR_QuestData["12496"]["Objectives"] = "Cerca Alexstrasza, la Legatrice della Vita, al Tempio della Lega dei Draghi a Dragonblight."
end
if not QTR_QuestData["12496"]["Completion"] or QTR_QuestData["12496"]["Completion"] == "" then
  QTR_QuestData["12496"]["Completion"] = "Sei venuto cercando il mio consiglio, mortale. Lo so, ma sai tu cosa stai affrontando?NEW_LINENEW_LINE<Alexstrasza indica a nord>NEW_LINENEW_LINEA nord di qui si trovano le terre desolate di Galakrond, progenitore dei draghi. È da Galakrond che i Titani crearono gli Aspett. Immaginate, quindi, il potere di Galakrond. Le sue dimensioni da sole erano maggiori di quelle di tutti gli Aspett! Ora cerca di capire cosa fa il Flagello nella Grande Palude dei Draghi.NEW_LINENEW_LINEI draghi di gelo, mortale, dovrebbero essere l'ultima delle tue preoccupazioni."
end

QTR_QuestData["12497"] = QTR_QuestData["12497"] or {}
if not QTR_QuestData["12497"]["Title"] or QTR_QuestData["12497"]["Title"] == "" then
