if not QTR_QuestData["12497"]["Description"] or QTR_QuestData["12497"]["Description"] == "" then
  QTR_QuestData["12497"]["Description"] = "Sulla cima della Spirale Malvagia, il Grande Necrolord del Flagello, Antiok, è seduto sulle spalle del signore dei giganti delle tempeste ricostruito, Thiassi. Da lì, comanda le armate di non morti affinché lavorino giorno e notte per dissotterrare le enormi ossa di Galakrond. Se dovessero riuscire a risvegliare Galakrond, tutti i vostri sforzi saranno stati vani.NEW_LINENEW_LINESebbene io non possa invocare tutta la furia del Red Dragonflight per assisterti nel tuo viaggio, ti concederò la mia benedizione. Ora vai e parla con il mio maggiordomo, Torastrasza."
end
if not QTR_QuestData["12497"]["Objectives"] or QTR_QuestData["12497"]["Objectives"] == "" then
