if not QTR_QuestData["12497"]["Completion"] or QTR_QuestData["12497"]["Completion"] == "" then
  QTR_QuestData["12497"]["Completion"] = "Il coraggio dei mortali non smette mai di stupirmi. La morte fissa su di te il suo sguardo gelido e, in risposta, tu ti sollevi per sfidare la sua affermazione! Ecco perché la vostra specie è così amata... e così odiato.NEW_LINENEW_LINEAnche se il Red Dragonflight è impegnato in una guerra con Malygos, c'è qualcosa che possiamo fare per aiutare."
end

QTR_QuestData["12498"] = QTR_QuestData["12498"] or {}
