if not QTR_QuestData["13007"]["Objectives"] or QTR_QuestData["13007"]["Objectives"] == "" then
  QTR_QuestData["13007"]["Objectives"] = "Utilizza un Jormungar addomesticato per sconfiggere il Colosso di Ferro e torna da Bouldercrag il Modellatore presso il Rifugio di Bouldercrag."
end
if not QTR_QuestData["13007"]["Progress"] or QTR_QuestData["13007"]["Progress"] == "" then
  QTR_QuestData["13007"]["Progress"] = "Avete sconfitto il colosso di ferro e salvato il rifugio dalla distruzione?"
end
if not QTR_QuestData["13007"]["Completion"] or QTR_QuestData["13007"]["Completion"] == "" then
  QTR_QuestData["13007"]["Completion"] = "Ce l'abbiamo fatta, ce l'abbiamo davvero fatta! Il rifugio è salvo e i forgiati della tempesta sono stati sconfitti! Dobbiamo avvertire Brann prima che Loken si metta in testa di cercare di ricostruire le sue forze. L'unico modo per assicurare la vittoria che avete ottenuto oggi è entrare a Ulduar e sconfiggere Loken per sempre!"
end

QTR_QuestData["13008"] = QTR_QuestData["13008"] or {}
