if not QTR_QuestData["13037"]["Progress"] or QTR_QuestData["13037"]["Progress"] == "" then
  QTR_QuestData["13037"]["Progress"] = "Ritorna da Xarantaur al campo di Tunka'lo nelle Cime Tempestose."
end
if not QTR_QuestData["13037"]["Completion"] or QTR_QuestData["13037"]["Completion"] == "" then
  QTR_QuestData["13037"]["Completion"] = "Anche il capo sta iniziando a perdere i suoi ricordi? Il passato viene riscritto davanti ai nostri occhi e se non scopriremo chi c'è dietro, l'intera eredità di Stormhoof potrebbe essere persa per sempre."
end

QTR_QuestData["13038"] = QTR_QuestData["13038"] or {}
if not QTR_QuestData["13038"]["Title"] or QTR_QuestData["13038"]["Title"] == "" then
  QTR_QuestData["13038"]["Title"] = "Distorsioni nel tempo"
end
if not QTR_QuestData["13038"]["Description"] or QTR_QuestData["13038"]["Description"] == "" then
  QTR_QuestData["13038"]["Description"] = "Questa, la tomba dei guerrieri di Tunka'lo, dovrebbe essere un luogo tranquillo, lontano dal terrore degli elementi.NEW_LINENEW_LINELe Ghiacciaie Profonde sono state invase da una forza strana, che disturba gli spiriti dei caduti e offusca i miei ricordi della mia stessa vita.NEW_LINENEW_LINEÈ come se le nostre azioni e i nostri ricordi stessero venendo cancellati dalla storia.NEW_LINENEW_LINEIn vita, questo totem era un simbolo della mia autorità. È l'ultimo vero legame che ho con questo mondo. Prendilo, usalo per ripristinare la calma nella tomba, e poi restituiscilo al campo di Tunka'lo."
end
if not QTR_QuestData["13038"]["Objectives"] or QTR_QuestData["13038"]["Objectives"] == "" then
  QTR_QuestData["13038"]["Objectives"] = "Usa il Totem del Capo per chiudere 4 Fenditure di Ghiaccio, quindi porta il totem a Xarantaur presso il campo di Tunka'lo."
end
if not QTR_QuestData["13038"]["Progress"] or QTR_QuestData["13038"]["Progress"] == "" then
  QTR_QuestData["13038"]["Progress"] = "Cosa mi hai portato dalla tomba?"
end
if not QTR_QuestData["13038"]["Completion"] or QTR_QuestData["13038"]["Completion"] == "" then
  QTR_QuestData["13038"]["Completion"] = "Lo spirito del capo ti ha detto di portarmelo?NEW_LINENEW_LINE<Xarantaur esamina il totem>NEW_LINENEW_LINEAh, capisco cosa intendeva. Dicendoti di usare questo totem per chiudere le fratture nel profondo, ci ha dato un indizio su cosa sta succedendo alla linea temporale. Un capo saggio, questo Swiftspear, che veglia sul suo popolo anche nella morte."
end

