QTR_QuestData["13040"] = QTR_QuestData["13040"] or {}
if not QTR_QuestData["13040"]["Title"] or QTR_QuestData["13040"]["Title"] == "" then
  QTR_QuestData["13040"]["Title"] = "Curare l'incurabile"
