if not QTR_QuestData["13042"]["Progress"] or QTR_QuestData["13042"]["Progress"] == "" then
  QTR_QuestData["13042"]["Progress"] = "Non hai ancora completato ciò che ti ho chiesto.NEW_LINENEW_LINEPer favore, vada via e non ritorni finché non avrà completato l'azione, altrimenti sarò molto arrabbiato."
