QTR_QuestData["13044"] = QTR_QuestData["13044"] or {}
if not QTR_QuestData["13044"]["Title"] or QTR_QuestData["13044"]["Title"] == "" then
  QTR_QuestData["13044"]["Title"] = "Se ci sono sopravvissuti..."
