QTR_QuestData["13048"] = QTR_QuestData["13048"] or {}
if not QTR_QuestData["13048"]["Title"] or QTR_QuestData["13048"]["Title"] == "" then
  QTR_QuestData["13048"]["Title"] = "Dove è andato storto il tempo"
end
if not QTR_QuestData["13048"]["Description"] or QTR_QuestData["13048"]["Description"] == "" then
  QTR_QuestData["13048"]["Description"] = "Il Martello della Leggenda può aiutarci a correggere i danni alla linea temporale, ma solo se riusciamo a scoprire dove la storia è stata originariamente corrotta.NEW_LINENEW_LINESecondo il capo Swiftspear e le tue scoperte a Frostfloe Deep, sappiamo che il cambiamento è avvenuto intorno al momento della morte di Stormhoof.NEW_LINENEW_LINEOra, devi andare a Howling Hollow, a nord del campo, e ispezionare i luoghi di sepoltura che i servitori del Vento Boreale hanno già distrutto. Il Lorehammer reagirà agli artefatti dell'era di Stormhoof e si sintonizzerà sul momento giusto."
end
if not QTR_QuestData["13048"]["Objectives"] or QTR_QuestData["13048"]["Objectives"] == "" then
  QTR_QuestData["13048"]["Objectives"] = "Utilizza il Lorehammer sui manufatti dei Taunka per accordarlo all'epoca di Stormhoof. Una volta che sarà stato accordato a 6 reliquie dell'epoca di Stormhoof, restituirle a Xarantaur al campo di Tunka'lo."
end
if not QTR_QuestData["13048"]["Progress"] or QTR_QuestData["13048"]["Progress"] == "" then
  QTR_QuestData["13048"]["Progress"] = "Hai accordato il Lorehammer all'epoca di Stormhoof?"
end
if not QTR_QuestData["13048"]["Completion"] or QTR_QuestData["13048"]["Completion"] == "" then
