end

QTR_QuestData["13049"] = QTR_QuestData["13049"] or {}
if not QTR_QuestData["13049"]["Title"] or QTR_QuestData["13049"]["Title"] == "" then
  QTR_QuestData["13049"]["Title"] = "Le armi dell'eroe"
end
if not QTR_QuestData["13049"]["Description"] or QTR_QuestData["13049"]["Description"] == "" then
  QTR_QuestData["13049"]["Description"] = "Non tutti i registri del campo sono stati ancora corrotti. Il mio staff mi ha aiutato a trovare quei registri che riflettono la vera cronologia.NEW_LINENEW_LINESono d'accordo che Stormhoof ricevette un'onorata sepoltura tra gli anziani del villaggio nel livello inferiore di Howling Hollow, a nord.NEW_LINENEW_LINELa maggior parte delle tombe lì sono già state distrutte, e i loro contenuti sono stati presi come trofei dai seguaci del Vento del Nord. Vai nella radura e cerca di recuperare la lancia e l'armatura di Stormhoof dagli scionieri della tempesta che le hanno prese."
end
if not QTR_QuestData["13049"]["Objectives"] or QTR_QuestData["13049"]["Objectives"] == "" then
  QTR_QuestData["13049"]["Objectives"] = "Recupera la lancia di Stormhoof e la cotta di maglia di Stormhoof e riportali a Xarantaur a Camp Tunka'lo."
end
if not QTR_QuestData["13049"]["Progress"] or QTR_QuestData["13049"]["Progress"] == "" then
  QTR_QuestData["13049"]["Progress"] = "Avete trovato l'arma e l'armatura di Stormhoof?"
end
if not QTR_QuestData["13049"]["Completion"] or QTR_QuestData["13049"]["Completion"] == "" then
  QTR_QuestData["13049"]["Completion"] = "Siamo fortunati che tu abbia recuperato questi oggetti intatti, YOUR_NAME. Con essi, posso usare il Lorehammer per inviarti indietro nel tempo, all'epoca in cui il Vento del Nord ha iniziato a corrompere la vera linea temporale. È l'unico modo in cui possiamo ripristinare la vera storia di questo luogo."
end

QTR_QuestData["13050"] = QTR_QuestData["13050"] or {}
if not QTR_QuestData["13050"]["Title"] or QTR_QuestData["13050"]["Title"] == "" then
  QTR_QuestData["13050"]["Title"] = "Veranus"
end
if not QTR_QuestData["13050"]["Description"] or QTR_QuestData["13050"]["Description"] == "" then
  QTR_QuestData["13050"]["Description"] = "Se devo lanciare un attacco contro l'esercito di mio fratello, avrò bisogno di un modo per aggirarlo.NEW_LINENEW_LINEHo liberato il mio drago da sella nella natura selvaggia anni fa. Veranus era magnifica. Era la leader del suo stesso gruppo -- a cui è ora tornata.NEW_LINENEW_LINETrovarla sarà difficile, ma forse c'è un modo. Conserva il suo vecchio nido vuoto per puro orgoglio. È una matriarca solo di nome, perché ha superato l'età fertile.NEW_LINENEW_LINEPortami delle piccole uova dagli altri nidi vicino a Brunnhildar. Penso di avere un'idea."
end
