if not QTR_QuestData["13124"]["Description"] or QTR_QuestData["13124"]["Description"] == "" then
  QTR_QuestData["13124"]["Description"] = "La battaglia continua, YOUR_NAME. In qualche modo siamo riusciti a evitare di essere scoperti e a continuare i nostri tentativi di sventare i piani di Malygos. Tuttavia, è qui che finiscono le buone notizie e iniziano quelle brutte.NEW_LINENEW_LINEI nostri migliori sforzi hanno avuto scarso o nessun effetto. Malygos e i suoi seguaci diventano sempre più potenti giorno dopo giorno. E ora, la nostra ultima squadra d'assalto è stata catturata e tenuta prigioniera nell'Oculus.NEW_LINENEW_LINEDobbiamo tentare un salvataggio! Belgaristrasz e i suoi compagni sono preziosi per la nostra causa. Possiamo contare su di te, YOUR_NAME?"
end
if not QTR_QuestData["13124"]["Objectives"] or QTR_QuestData["13124"]["Objectives"] == "" then
  QTR_QuestData["13124"]["Objectives"] = "Raelorasz vuole che tu entri nell'Oculus e salvi Belgaristrasz e i suoi compagni."
end
if not QTR_QuestData["13124"]["Completion"] or QTR_QuestData["13124"]["Completion"] == "" then
  QTR_QuestData["13124"]["Completion"] = "Ascolta attentamente, YOUR_RACE.NEW_LINENEW_LINEIl tuo lavoro qui è appena iniziato!"
end

QTR_QuestData["13125"] = QTR_QuestData["13125"] or {}
if not QTR_QuestData["13125"]["Title"] or QTR_QuestData["13125"]["Title"] == "" then
