if not QTR_QuestData["13129"]["Description"] or QTR_QuestData["13129"]["Description"] == "" then
  QTR_QuestData["13129"]["Description"] = "Troppo pigri per il loro stesso bene... Aspetta! So come insegnarglielo!NEW_LINENEW_LINE<Kurzel strappa una lunga striscia di tessuto dalla sua camicetta e te la porge.>NEW_LINENEW_LINEQui, YOUR_RACE, prendi questo. Impregnalo con i resti di quel fastidioso lich lì e riportalo a Mack all'accampamento.NEW_LINENEW_LINEDopo che i ragazzi si saranno tormentati un po' con il senso di colpa, mi farò avanti e li perdonerò.NEW_LINENEW_LINEImpareranno a non lasciare che una signora si allontani da sola!"
end
if not QTR_QuestData["13129"]["Objectives"] or QTR_QuestData["13129"]["Objectives"] == "" then
  QTR_QuestData["13129"]["Objectives"] = "Kurzel vuole che tu utilizzi gli Scarti di Camicia di Kurzel sulla salma di Novos l'Evocatore, quindi porta il Tessuto Macchiato di Essenza a Mack."
end
if not QTR_QuestData["13129"]["Progress"] or QTR_QuestData["13129"]["Progress"] == "" then
