end
if not QTR_QuestData["13132"]["Completion"] or QTR_QuestData["13132"]["Completion"] == "" then
  QTR_QuestData["13132"]["Completion"] = "Magnifico! Forse ora i miei compagni potranno riposare in pace.NEW_LINENEW_LINEEcco a te, ragazzo. Non si dica che il vecchio Brigg non sia stato generoso con coloro che gli hanno mostrato gentilezza.NEW_LINENEW_LINEBuon affare con te."
end

QTR_QuestData["13133"] = QTR_QuestData["13133"] or {}
