if not QTR_QuestData["13137"]["Description"] or QTR_QuestData["13137"]["Description"] == "" then
  QTR_QuestData["13137"]["Description"] = "Sulla cima della montagna più alta a sud-ovest, che domina Jotunheim, si erge la Battlescar Spire. È un luogo di grande importanza per i vrykul, secondo solo a Valhalas per quanto riguarda i luoghi in cui preferiscono svolgere combattimenti onorevoli.NEW_LINENEW_LINEAffronteremo un combattimento tutt'altro che onorevole.NEW_LINENEW_LINERadunate i vostri compagni e volate verso la torre. Quando sarete pronti, accendete il fuoco di segnalazione e io apparirò nel corpo di Iskalder.NEW_LINENEW_LINECombatteremo, vincerete, e Vardmadra sarà sicuramente presente per assistere alla battaglia!"
end
if not QTR_QuestData["13137"]["Objectives"] or QTR_QuestData["13137"]["Objectives"] == "" then
