QTR_QuestData["13138"] = QTR_QuestData["13138"] or {}
if not QTR_QuestData["13138"]["Title"] or QTR_QuestData["13138"]["Title"] == "" then
  QTR_QuestData["13138"]["Title"] = "Sto fondendo... Sto fondendo!"
end
if not QTR_QuestData["13138"]["Description"] or QTR_QuestData["13138"]["Description"] == "" then
  QTR_QuestData["13138"]["Description"] = "<Olakin gira uno dei frammenti con un pugno guantato.>NEW_LINENEW_LINEQuesti potevano perforare le armature con sufficiente forza. Dobbiamo scoprire di cosa sono fatti e cosa il Re dei Lich intende farne.NEW_LINENEW_LINEA est, adiacente alla Rocca della Corona di Ghiaccio, si trova Malykriss. Secondo le poche informazioni che abbiamo, è pieno di attrezzature per la fusione e la lavorazione dei metalli. Porta questi frammenti lì e falli fondere in uno dei forni aperti al livello inferiore di Malykriss. Una volta che il metallo è stato riformato, possiamo identificarlo."
end
if not QTR_QuestData["13138"]["Objectives"] or QTR_QuestData["13138"]["Objectives"] == "" then
  QTR_QuestData["13138"]["Objectives"] = "Utilizzate la Borsa di Frammenti Taglienti vicino a uno dei forni del livello inferiore di Malykriss. Ritorna da Crusader Olakin Sainrith a Blackwatch con la Barra di Metallo Fuso."
end
if not QTR_QuestData["13138"]["Progress"] or QTR_QuestData["13138"]["Progress"] == "" then
