end
if not QTR_QuestData["13138"]["Completion"] or QTR_QuestData["13138"]["Completion"] == "" then
  QTR_QuestData["13138"]["Completion"] = "Non c'è dubbio, questa è saronite grezza. Abbiamo visto armi create con questo materiale nelle mani degli eletti del Re dei Lich, ma è la prima volta che viene utilizzato per armare qualcos'altro. Le dimensioni di quella operazione mineraria devono essere enormi."
end

QTR_QuestData["13139"] = QTR_QuestData["13139"] or {}
if not QTR_QuestData["13139"]["Title"] or QTR_QuestData["13139"]["Title"] == "" then
  QTR_QuestData["13139"]["Title"] = "Nel cuore ghiacciato di Northrend"
