if not QTR_QuestData["13139"]["Description"] or QTR_QuestData["13139"]["Description"] == "" then
  QTR_QuestData["13139"]["Description"] = "Silas e Spitzpatrick hanno approvato i materiali e il carburante necessari per iniziare la costruzione di Justice Keep. Grazie a te e alla Spada d'Ebano, la presenza del Flagello a Scourgeholme è stata decimata e i loro luogotenenti sono stati sconfitti.NEW_LINENEW_LINEHo scelto il luogo in cui inizieremo i lavori, ma prima dovete consegnare il mio rapporto al Grand'ammiraglio Tirion Fordring. Inizieremo la nostra marcia verso Icecrown su suo comando.NEW_LINE"
end
if not QTR_QuestData["13139"]["Objectives"] or QTR_QuestData["13139"]["Objectives"] == "" then
  QTR_QuestData["13139"]["Objectives"] = "Consegna il rapporto di Padre Gustav al Alto Lorde Tirion Fordring presso l'Avanguardia Argentata a Ghiacciacque.NEW_LINE"
end
