if not QTR_QuestData["13140"]["Completion"] or QTR_QuestData["13140"]["Completion"] == "" then
  QTR_QuestData["13140"]["Completion"] = "Queste piastre corrispondono quasi esattamente ai frammenti. Devono utilizzare talee prelevate da queste piante per \"migliorare\" i ghoul prodotti qui. Il Flagello sembra essere abbastanza disperato da trasformare qualsiasi cosa in un'arma. Per questo, tanto più dobbiamo accelerare la nostra distruzione di questo luogo abominevole!"
end

QTR_QuestData["13141"] = QTR_QuestData["13141"] or {}
if not QTR_QuestData["13141"]["Title"] or QTR_QuestData["13141"]["Title"] == "" then
