if not QTR_QuestData["13663"]["Description"] or QTR_QuestData["13663"]["Description"] == "" then
  QTR_QuestData["13663"]["Description"] = "Dobbiamo scoprire chi ha mandato il Cavaliere Nero al torneo e cosa il suo padrone spera di ottenere eliminando i concorrenti.NEW_LINENEW_LINELa Kirin Tor si è offerta di aiutarci in merito e ci ha fornito qualcosa per aiutarci nella nostra ricerca.NEW_LINENEW_LINEPorta questo guinzaglio incantato al campo del Cavaliere Nero, situato sul bordo orientale dell'area del torneo, e usalo per prendere il controllo del grifone del Cavaliere Nero. La magia del guinzaglio forzerà il grifone a portarti a casa del suo padrone. Esamina l'oggetto e riporta qualsiasi cosa tu trovi."
end
if not QTR_QuestData["13663"]["Objectives"] or QTR_QuestData["13663"]["Objectives"] == "" then
  QTR_QuestData["13663"]["Objectives"] = "Usa il {Bridle Incantato} per prendere il controllo del Grifone del Cavaliere Nero e cavalcalo fino alla sua destinazione. Una volta arrivati, recuperate l'invito rubato al torneo e gli ordini del Cavaliere Nero e portateli al Crociato Rhydalla ai Campi del Torneo d'Argento."
end
if not QTR_QuestData["13663"]["Progress"] or QTR_QuestData["13663"]["Progress"] == "" then
  QTR_QuestData["13663"]["Progress"] = "Cosa hai scoperto?"
end
if not QTR_QuestData["13663"]["Completion"] or QTR_QuestData["13663"]["Completion"] == "" then
  QTR_QuestData["13663"]["Completion"] = "Il volto di Crusader Rhydalla impallidisce mentre legge gli ordini.NEW_LINENEW_LINEQuesto può significare solo una cosa, YOUR_NAME. Il Cavaliere Nero è un membro del Culto dei Dannati ed è stato inviato da Arthas per interrompere il torneo!NEW_LINENEW_LINEIl Cavaliere Nero si è dimostrato un combattente temibile, e dovrete essere altrettanto bravi se volete affrontarlo. Quando sarete un campione, tornate da me e troveremo un modo per assicurare la sua sconfitta."
end

QTR_QuestData["13664"] = QTR_QuestData["13664"] or {}
if not QTR_QuestData["13664"]["Title"] or QTR_QuestData["13664"]["Title"] == "" then
  QTR_QuestData["13664"]["Title"] = "La caduta del Cavaliere Nero"
