if not QTR_QuestData["13887"]["Title"] or QTR_QuestData["13887"]["Title"] == "" then
  QTR_QuestData["13887"]["Title"] = "Uova di Venomhide"
end
if not QTR_QuestData["13887"]["Description"] or QTR_QuestData["13887"]["Description"] == "" then
  QTR_QuestData["13887"]["Description"] = "Ora che hai sviluppato un'immunità alla tossina dei Venomhide, puoi maneggiare in sicurezza gli animali e le loro uova. I Venomhide sono feroci e devono essere addestrati fin dal momento in cui schiudono.NEW_LINENEW_LINESe vuoi cavalcarne uno, avrai bisogno di un uovo non ancora schiuso. Sparseggianti nelle Paludi, si trovano numerosi nidi di ravasauro. Cercate le uova con il guscio di colore più chiaro: sono quelle che faranno nascere i venomhide.NEW_LINENEW_LINESe mi porti diverse uova, ti permetterò di tenere una di esse e allevare il suo piccolo, con la mia guida."
end
if not QTR_QuestData["13887"]["Objectives"] or QTR_QuestData["13887"]["Objectives"] == "" then
  QTR_QuestData["13887"]["Objectives"] = "Porta 4 Porta le uova di Ravasauro Veleno a Mor'vek nella parte sud-orientale delle Paludi Mortali."
end
if not QTR_QuestData["13887"]["Progress"] or QTR_QuestData["13887"]["Progress"] == "" then
  QTR_QuestData["13887"]["Progress"] = "Hai trovato quelle uova?"
end
if not QTR_QuestData["13887"]["Completion"] or QTR_QuestData["13887"]["Completion"] == "" then
  QTR_QuestData["13887"]["Completion"] = "Ottimo lavoro. Sinceramente, sono stupito che tu sia riuscito a trovarne così tante. Sembra che con ogni covata, il loro numero diminuisca.NEW_LINENEW_LINETi permetterò di far crescere uno dei giovani Ravasauri dalla pelle velenosa. Non dovrebbe essere timido e ti farà capire cosa gli serve."
end

