QTR_QuestData["14090"] = QTR_QuestData["14090"] or {}
if not QTR_QuestData["14090"]["Title"] or QTR_QuestData["14090"]["Title"] == "" then
  QTR_QuestData["14090"]["Title"] = "Gormok vuole i suoi snobold."
end
if not QTR_QuestData["14090"]["Description"] or QTR_QuestData["14090"]["Description"] == "" then
  QTR_QuestData["14090"]["Description"] = "Due dei miei uomini sono già stati uccisi nel tentativo di catturare il magnatauro chiamato Gormok l'Impilatore, ma la creatura continua a infuriarsi. Ulula per ore lamentandosi di non avere più il suo amato snobold.NEW_LINENEW_LINESe la Crociata d'Argento non volesse usare questa creatura nell'arena, l'ucciderei io stesso. Forse è ora di portare i suoi giocattoli alla bestia. Prendi questa rete e recati a Garm's Bane, nella parte sud-est delle Cime Tempestose. Si trova appena a nord-est di K3. Catturate alcuni di quei snobold e pregate la Luce, sperando di averne trovato uno giusto."
end
if not QTR_QuestData["14090"]["Objectives"] or QTR_QuestData["14090"]["Objectives"] == "" then
  QTR_QuestData["14090"]["Objectives"] = "Utilizza la Rete Pesante per catturare 8 Portate i Seguaci Accecati dalla Neve e consegnali a Savinia Loresong ai Campi del Torneo d'Argento."
end
if not QTR_QuestData["14090"]["Progress"] or QTR_QuestData["14090"]["Progress"] == "" then
  QTR_QuestData["14090"]["Progress"] = "Riuscite a radunare quegli snobold? La rabbia di Gormok non sembra diminuire."
end
if not QTR_QuestData["14090"]["Completion"] or QTR_QuestData["14090"]["Completion"] == "" then
  QTR_QuestData["14090"]["Completion"] = "Più velocemente ci liberiamo di queste cose disgustose e le rinchiudiamo nella loro gabbia, più velocemente il mio umore migliorerà. Vorrei che la Crociata d'Argento avesse dato ai Sunreaver la cura di questa creatura. Sono abbastanza simili che dovrebbero essere in grado di capirsi."
end

QTR_QuestData["14092"] = QTR_QuestData["14092"] or {}
if not QTR_QuestData["14092"]["Title"] or QTR_QuestData["14092"]["Title"] == "" then
  QTR_QuestData["14092"]["Title"] = "Colazione da campioni"
end
if not QTR_QuestData["14092"]["Description"] or QTR_QuestData["14092"]["Description"] == "" then
  QTR_QuestData["14092"]["Description"] = "Ora che il colosseo è stato completato, la Crociata d'Argento ci ha chiesto di aiutare a prendersi cura delle creature con cui i campioni si sfideranno.NEW_LINENEW_LINEI giganteschi jormungar hanno forse la dieta più strana; crescono forti mangiando le uova della propria specie, e le uova migliori provengono dai jormungar più grandi.NEW_LINENEW_LINEPorta questo tamburo alle Pendici dei Ghiacciai nella zona centrale delle Cime Tempestose e suonalo vicino ai cumuli di neve che vedi lì. Il rumore risveglierà il jormungar abissale. Uccidili, raccogli le loro sacche di uova e torna all'area del torneo."
end
if not QTR_QuestData["14092"]["Objectives"] or QTR_QuestData["14092"]["Objectives"] == "" then
  QTR_QuestData["14092"]["Objectives"] = "Acquisire 4 Raccogli le Sacche di Uova di Jormungar e portale a Tylos Dawnrunner ai Campi del Torneo d'Argento."
end
if not QTR_QuestData["14092"]["Progress"] or QTR_QuestData["14092"]["Progress"] == "" then
  QTR_QuestData["14092"]["Progress"] = "Riuscite a trovare quelle uova? I jormungar diventeranno aggressivi se non vengono nutriti."
end
if not QTR_QuestData["14092"]["Completion"] or QTR_QuestData["14092"]["Completion"] == "" then
  QTR_QuestData["14092"]["Completion"] = "Avvertirò i crociati che sei appena tornato con un carico di cibo, mentre il Patto d'Argento era inattivo."
end

QTR_QuestData["14095"] = QTR_QuestData["14095"] or {}
if not QTR_QuestData["14095"]["Title"] or QTR_QuestData["14095"]["Title"] == "" then
  QTR_QuestData["14095"]["Title"] = "Identificare i resti"
end
if not QTR_QuestData["14095"]["Description"] or QTR_QuestData["14095"]["Description"] == "" then
  QTR_QuestData["14095"]["Description"] = "Un dente intero proveniente da una Kraken morta è una scoperta davvero rara. Il Crociato Silverdawn vorrà vedere questo."
end
if not QTR_QuestData["14095"]["Objectives"] or QTR_QuestData["14095"]["Objectives"] == "" then
  QTR_QuestData["14095"]["Objectives"] = "Porta il dente di kraken a Crusader Silverdawn come prova della tua vittoria."
end
if not QTR_QuestData["14095"]["Progress"] or QTR_QuestData["14095"]["Progress"] == "" then
  QTR_QuestData["14095"]["Progress"] = "Cosa hai scoperto, campione?"
