end
if not QTR_QuestData["14107"]["Progress"] or QTR_QuestData["14107"]["Progress"] == "" then
  QTR_QuestData["14107"]["Progress"] = "Avete portato la pace alle anime degli eroi caduti?"
end
if not QTR_QuestData["14107"]["Completion"] or QTR_QuestData["14107"]["Completion"] == "" then
  QTR_QuestData["14107"]["Completion"] = "Avete reso un grande servizio ai nostri caduti e ci avete risparmiato la necessità di affrontarli di nuovo sul campo di battaglia. Mentre la nostra campagna contro il Flagello prosegue, mi ritrovo a pensare al mio stesso destino.NEW_LINENEW_LINESe dovessi cadere, YOUR_NAME, Vorrei che qualcuno come te facesse per me quello che hai fatto per gli spiriti dei caduti oggi. Non avrei mai sopportato l'idea di costringere i miei stessi fratelli a uccidermi ancora e ancora."
end

QTR_QuestData["14108"] = QTR_QuestData["14108"] or {}
