if not QTR_QuestData["14108"]["Description"] or QTR_QuestData["14108"]["Description"] == "" then
  QTR_QuestData["14108"]["Description"] = "I Sunreavers e il Patto d'Argento hanno inviato delle navi a nord per attaccare i Kvaldir a Hrothgar's Landing, ma sono state intercettate e trattenute da una nave d'assalto Kvaldir.  Per peggiorare le cose, i Kvaldir hanno trovato un modo per evocare l'odioso Kraken che vive sotto il Mare del Nord.  Se qualcuno a bordo vuole sopravvivere, quel Kraken deve essere allontanato e il rituale di evocazione dei Kvaldir... interrotto.NEW_LINENEW_LINECavaliere, prendi queste lance e un Ippogrifo Argento ti porterà sul campo di battaglia."
end
if not QTR_QuestData["14108"]["Objectives"] or QTR_QuestData["14108"]["Objectives"] == "" then
  QTR_QuestData["14108"]["Objectives"] = "Crusader Silverdawn vuole che tu cavalchi un Ippogrifo Argentato, poi 6 Elimina le Lame Infuocate al Kraken del Mare del Nord 3 Profondi chiamatori vrykuli.NEW_LINENEW_LINEPotete trovare gli Ippogrifo Argento proprio fuori dalla tenda della Crociata d'Argento, presso l'area del torneo."
end
if not QTR_QuestData["14108"]["Progress"] or QTR_QuestData["14108"]["Progress"] == "" then
  QTR_QuestData["14108"]["Progress"] = "Hai già allontanato la Kraken? Sbrigati, Crociato! Non c'è molto tempo."
end
if not QTR_QuestData["14108"]["Completion"] or QTR_QuestData["14108"]["Completion"] == "" then
