if not QTR_QuestData["14111"]["Description"] or QTR_QuestData["14111"]["Description"] == "" then
  QTR_QuestData["14111"]["Description"] = "Hai fatto molta strada nel tuo addestramento, YOUR_NAME. Ora che hai padroneggiato i quattro elementi fondamentali, devi sforzarti di mantenere l'equilibrio tra tutti e quattro. C'è un vantaggio pratico in questa disciplina: con la pratica, potresti portare con te un solo artefatto invece di tutti e quattro i totem.NEW_LINENEW_LINEParla con il Presagente Eannu vicino alla Grande Fucina a Forgiardente. Lui ti aiuterà a perfezionare la tua padronanza degli elementi."
end
if not QTR_QuestData["14111"]["Objectives"] or QTR_QuestData["14111"]["Objectives"] == "" then
  QTR_QuestData["14111"]["Objectives"] = "Porta i tuoi quattro totem a Farseer Eannu a Forgiardente."
end
if not QTR_QuestData["14111"]["Progress"] or QTR_QuestData["14111"]["Progress"] == "" then
  QTR_QuestData["14111"]["Progress"] = "Gli spiriti si agitano dentro di te. Cosa ti porta a cercare l'aiuto del Circolo della Terra?"
end
if not QTR_QuestData["14111"]["Completion"] or QTR_QuestData["14111"]["Completion"] == "" then
  QTR_QuestData["14111"]["Completion"] = "Vedo che hai imparato a usare i quattro totem. Sei sulla strada per diventare uno con gli spiriti elementali, ma questo è solo l'inizio del tuo viaggio.NEW_LINENEW_LINEQui, accetta questo dono dal Circolo della Terra. Porta con te questo artefatto e avrai il potere di tutti e quattro gli elementi al tuo comando.NEW_LINENEW_LINEIl tuo addestramento deve continuare! Sento che per questo mondo ci attendono molte prove, e avremo bisogno del potere degli elementi al nostro fianco se vogliamo avere successo."
end

QTR_QuestData["14112"] = QTR_QuestData["14112"] or {}
if not QTR_QuestData["14112"]["Title"] or QTR_QuestData["14112"]["Title"] == "" then
  QTR_QuestData["14112"]["Title"] = "Cosa si dà da mangiare a uno yeti, in fondo?"
