QTR_QuestData["14141"] = QTR_QuestData["14141"] or {}
if not QTR_QuestData["14141"]["Title"] or QTR_QuestData["14141"]["Title"] == "" then
  QTR_QuestData["14141"]["Title"] = "Gormok vuole i suoi Snobold"
end
if not QTR_QuestData["14141"]["Description"] or QTR_QuestData["14141"]["Description"] == "" then
  QTR_QuestData["14141"]["Description"] = "Due dei miei uomini sono già stati uccisi nel tentativo di catturare il magnatauro chiamato Gormok l'Impilatore, ma la creatura continua a infuriarsi. Ulula per ore lamentandosi di non avere più il suo amato snobold.NEW_LINENEW_LINESe la Crociata d'Argento non volesse usare questa creatura nell'arena, l'ucciderei io stesso. Forse è ora di portare i suoi giocattoli alla bestia. Prendi questa rete e recati a Garm's Bane, nella parte sud-est delle Cime Tempestose. Si trova appena a nord-est di K3. Catturate alcuni di quei snobold e pregate alla Luce, sperando di averne trovato uno giusto."
end
if not QTR_QuestData["14141"]["Objectives"] or QTR_QuestData["14141"]["Objectives"] == "" then
  QTR_QuestData["14141"]["Objectives"] = "Utilizza la Rete Pesante per catturare 8 Portate i Seguaci Accecati dalla Neve e consegnali a Tylos Dawnrunner ai Campi del Torneo d'Argento."
end
if not QTR_QuestData["14141"]["Progress"] or QTR_QuestData["14141"]["Progress"] == "" then
  QTR_QuestData["14141"]["Progress"] = "Sei riuscito a radunare quegli snobold? La rabbia di Gormok non sembra diminuire."
end
if not QTR_QuestData["14141"]["Completion"] or QTR_QuestData["14141"]["Completion"] == "" then
  QTR_QuestData["14141"]["Completion"] = "Più velocemente ci liberiamo di queste cose disgustose e le rinchiudiamo nella loro gabbia, più velocemente il mio umore migliorerà. Vorrei che la Crociata d'Argento avesse dato al Patto d'Argento le cure riservate a questa creatura. Dovranno sporcarsi le mani quando inizierà la battaglia per la Rocca della Corona di Ghiaccio e ho la sensazione che si dimostreranno alleati fragili e inaffidabili."
end

QTR_QuestData["14142"] = QTR_QuestData["14142"] or {}
if not QTR_QuestData["14142"]["Title"] or QTR_QuestData["14142"]["Title"] == "" then
