QTR_QuestData["24869"] = QTR_QuestData["24869"] or {}
if not QTR_QuestData["24869"]["Title"] or QTR_QuestData["24869"]["Title"] == "" then
  QTR_QuestData["24869"]["Title"] = "Deprogrammazione"
end
if not QTR_QuestData["24869"]["Description"] or QTR_QuestData["24869"]["Description"] == "" then
  QTR_QuestData["24869"]["Description"] = "Avevamo sperato di inserire un agente all'interno del Culto dei Dannati, per fornirci informazioni privilegiate sulle macchinazioni del Re dei Lich, ma... ha sottovalutato il potere persuasivo di Arthas e della sua oscura serva, Lady Deathwhisper.NEW_LINENEW_LINEIl nostro uomo, Darnavan, ne fa parte ora.NEW_LINENEW_LINESe avete intenzione di affrontare l'Oratorio che vi aspetta, fate attenzione a Darnavan. Se riuscite a riportarlo a noi vivo, potremo tentare di annullare il lavaggio del cervello operato dal Culto."
end
if not QTR_QuestData["24869"]["Objectives"] or QTR_QuestData["24869"]["Objectives"] == "" then
  QTR_QuestData["24869"]["Objectives"] = "Sconfiggete Lady Deathwhisper assicurandovi che Darnavan sopravviva."
end
if not QTR_QuestData["24869"]["Progress"] or QTR_QuestData["24869"]["Progress"] == "" then
  QTR_QuestData["24869"]["Progress"] = "Torna da Infiltratore Minchar."
end
if not QTR_QuestData["24869"]["Completion"] or QTR_QuestData["24869"]["Completion"] == "" then
  QTR_QuestData["24869"]["Completion"] = "Grazie, YOUR_NAME!NEW_LINENEW_LINELe sono grato per aver salvato un amico che pensavo fosse perduto per sempre nelle grinfie del Culto. E la Crociata d'Argento ti è grata per le preziose informazioni che Darnavan porta con sé, frutto del suo tempo trascorso a vagare per le sale di questa Cittadella, come membro del Culto.NEW_LINENEW_LINEPer favore, prenda questo come segno della nostra gratitudine, e possa la Luce darle forza mentre si fa strada in questo luogo terribile."
end

QTR_QuestData["24870"] = QTR_QuestData["24870"] or {}
if not QTR_QuestData["24870"]["Title"] or QTR_QuestData["24870"]["Title"] == "" then
  QTR_QuestData["24870"]["Title"] = "Proteggere le fortificazioni"
