if not QTR_QuestData["24870"]["Description"] or QTR_QuestData["24870"]["Description"] == "" then
  QTR_QuestData["24870"]["Description"] = "Come se questo posto non fosse già abbastanza caotico, qui combattiamo una guerra su due fronti: da un lato il Flagello e, dall'altro, quei maledetti cani dell'Alleanza!NEW_LINENEW_LINESiamo qui per creare un'area di atterraggio sicura per le nostre navi, ma un gigante enorme dall'altra parte delle Fortificazioni sta lanciando detriti contro qualsiasi cosa si avvicini, impedendo alle nostre navi più piccole di avvicinarsi.NEW_LINENEW_LINESinceramente, è un po' troppo per noi da gestire, ma voi e i vostri compagni sembrate pronti alla sfida."
end
if not QTR_QuestData["24870"]["Objectives"] or QTR_QuestData["24870"]["Objectives"] == "" then
