QTR_QuestData["24872"] = QTR_QuestData["24872"] or {}
if not QTR_QuestData["24872"]["Title"] or QTR_QuestData["24872"]["Title"] == "" then
  QTR_QuestData["24872"]["Title"] = "Un po' di sollievo per un'anima tormentata"
end
if not QTR_QuestData["24872"]["Description"] or QTR_QuestData["24872"]["Description"] == "" then
  QTR_QuestData["24872"]["Description"] = "Prendi questo Cristallo della Vita e fai in modo che anche i tuoi compagni ne prendano uno. Contiene potenti energie provenienti dal rigoglioso Santuario dei Draghi a Dragonblight, ed è stato il mio segreto per resistere alle oscure magie di questo luogo per così tanto tempo.NEW_LINENEW_LINEQuando affronti Sindragosa, combatti contro di lei finché non è indebolita, e poi fai in modo che i tuoi compagni utilizzino questi Cristalli per far emergere l'essenza che è dormiente al suo interno. Se la sconfiggi, dovresti essere in grado di recuperarlo e restituirlo al Tempio della Lega dei Draghi a Dragonblight."
end
if not QTR_QuestData["24872"]["Objectives"] or QTR_QuestData["24872"]["Objectives"] == "" then
  QTR_QuestData["24872"]["Objectives"] = "Utilizza i Cristalli della Vita per preservare l'Essenza di Sindragosa."
end
if not QTR_QuestData["24872"]["Progress"] or QTR_QuestData["24872"]["Progress"] == "" then
  QTR_QuestData["24872"]["Progress"] = "Cosa tieni lì tra le mani, mortale?"
end
if not QTR_QuestData["24872"]["Completion"] or QTR_QuestData["24872"]["Completion"] == "" then
  QTR_QuestData["24872"]["Completion"] = "<Kalecgos sospira>NEW_LINENEW_LINETanto dolore, tanta distruzione inutile. Questi non sono stati tempi facili per i miei fratelli e sorelle. Ma grazie ai vostri sforzi, valorosi avventurieri, questa anima oscura, ma ancora nobile, potrebbe finalmente trovare la pace.NEW_LINENEW_LINERiposa ora, Sindragosa. Sei a casa..."
end

QTR_QuestData["24873"] = QTR_QuestData["24873"] or {}
if not QTR_QuestData["24873"]["Title"] or QTR_QuestData["24873"]["Title"] == "" then
  QTR_QuestData["24873"]["Title"] = "Incontro con i residui"
end
if not QTR_QuestData["24873"]["Description"] or QTR_QuestData["24873"]["Description"] == "" then
  QTR_QuestData["24873"]["Description"] = "Il professor Putricide si è barricato nel suo lurido laboratorio, sperimentando e perfezionando ceppi sempre più letali di peste da utilizzare contro di noi. Se solo potessimo ottenere campioni puri delle tossine, i nostri ricercatori potrebbero creare un antidoto che salverebbe innumerevoli vite.NEW_LINENEW_LINEMa c'è un problema: un campione adeguato dovrà mescolare due ceppi attivi all'interno di un organismo vivente. Se dovesse capitarti... la sfortuna... se non desidera diventare un simile ospite, per favore, torni immediatamente qui in modo che possiamo prelevare campioni per lo studio."
end
if not QTR_QuestData["24873"]["Objectives"] or QTR_QuestData["24873"]["Objectives"] == "" then
  QTR_QuestData["24873"]["Objectives"] = "Ritorna dall'alchimista Adrianna mentre sei infettato dalla Piaga Arancione e dalla Piaga Verde."
end
if not QTR_QuestData["24873"]["Progress"] or QTR_QuestData["24873"]["Progress"] == "" then
  QTR_QuestData["24873"]["Progress"] = "Torna da Adrianna all'interno della Rocca della Corona di Ghiaccio."
end
if not QTR_QuestData["24873"]["Completion"] or QTR_QuestData["24873"]["Completion"] == "" then
  QTR_QuestData["24873"]["Completion"] = "Finalmente, abbiamo esemplari viventi da studiare! Hai contribuito a salvare innumerevoli vite oggi, YOUR_NAME.NEW_LINENEW_LINEPer favore, accetti questo come segno di gratitudine per questa grande impresa."
end

QTR_QuestData["24874"] = QTR_QuestData["24874"] or {}
if not QTR_QuestData["24874"]["Title"] or QTR_QuestData["24874"]["Title"] == "" then
  QTR_QuestData["24874"]["Title"] = "Accelerazione del sangue"
end
if not QTR_QuestData["24874"]["Description"] or QTR_QuestData["24874"]["Description"] == "" then
  QTR_QuestData["24874"]["Description"] = "Questi succhiasangue del Flagello, che si chiamano San'layn, mi mettono i brividi. Uno dei nostri migliori uomini li stava tenendo sotto controllo. Ma questa mattina è stato imprudente ed è stato preso prigioniero. Al momento, è in fase di interrogatorio da parte della Regina stessa, e le sue grida risuonano attraverso le Sale Cremisi. Per favore, salvatelo prima che sia troppo tardi!"
end
if not QTR_QuestData["24874"]["Objectives"] or QTR_QuestData["24874"]["Objectives"] == "" then
  QTR_QuestData["24874"]["Objectives"] = "Salva l'infiltrato Minchar prima che venga giustiziato."
end
if not QTR_QuestData["24874"]["Progress"] or QTR_QuestData["24874"]["Progress"] == "" then
  QTR_QuestData["24874"]["Progress"] = "Parla con Minchar."
end
if not QTR_QuestData["24874"]["Completion"] or QTR_QuestData["24874"]["Completion"] == "" then
  QTR_QuestData["24874"]["Completion"] = "Uff, pensavo di essere spacciato! Ho sentito parlare di un rituale di resurrezione che si svolgeva in queste Sale e sono entrato per dare un'occhiata più da vicino, ma uno di quei maledetti vampiri mi ha scoperto. Mi hanno legato qui, drenando la mia energia vitale e sperando che mi spezzassi e rivelassi i nostri piani d'attacco. Come se io sapessi cosa ha in mente Tirion!NEW_LINENEW_LINEPer favore, prenda questi bottini di guerra come un piccolo segno di gratitudine per avermi salvato la vita."
end

